using System.Net.Mail;
using CondoManager.Application;
using CondoManager.Domain;
using Microsoft.EntityFrameworkCore;
namespace CondoManager.Infrastructure;
public sealed partial class MeetingService
{
 private async Task<ParticipantsPreview> Snapshot(CondominiumMeeting row,CancellationToken ct){if(row.CurrentSnapshotId==null)throw new InvalidOperationException("Consolidare prima gli aventi diritto.");var s=await db.MeetingSnapshots.SingleAsync(x=>x.Id==row.CurrentSnapshotId&&x.MeetingId==row.Id,ct);return Read<ParticipantsPreview>(s.ContentJson);}
 public async Task<ParticipantsPreview> PreviewParticipants(Guid condo,Guid id,ParticipantsInput i,CancellationToken ct){current.RequireWrite();await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.RepeatableRead,ct);var row=await Find(condo,id,ct);row.CheckVersion(i.ExpectedVersion);var result=await BuildParticipants(row,i,ct);await tx.CommitAsync(ct);return result;}
 private async Task<ParticipantsPreview> BuildParticipants(CondominiumMeeting row,ParticipantsInput i,CancellationToken ct)
 {
  Guard.Dates(i.ReferenceDate,null);Guard.Text(i.Reason);if(i.Representatives.Select(x=>x.PropertyUnitId).Distinct().Count()!=i.Representatives.Count)throw new ArgumentException("Scelta rappresentante duplicata.");
  var units=await db.PropertyUnits.Where(x=>x.CondominiumId==row.CondominiumId).OrderBy(x=>x.Code).ThenBy(x=>x.Id).ToListAsync(ct);var unitIds=units.Select(x=>x.Id).ToArray();
  var holdings=await db.OwnershipPeriods.Where(x=>unitIds.Contains(x.PropertyUnitId)&&x.ValidFrom<=i.ReferenceDate&&(x.ValidTo==null||x.ValidTo>=i.ReferenceDate)&&x.Role!=UnitPersonRole.Tenant).OrderBy(x=>x.Id).ToListAsync(ct);
  units=units.Where(x=>x.IsActive||holdings.Any(h=>h.PropertyUnitId==x.Id)).ToList();if(i.Representatives.Any(r=>!units.Any(u=>u.Id==r.PropertyUnitId)))throw new NotFoundException();
  var personIds=holdings.Select(x=>x.PersonId).Distinct().ToArray();var people=await db.People.Where(x=>personIds.Contains(x.Id)).OrderBy(x=>x.Id).ToListAsync(ct);
  AllocationTable? table=null;var entries=new List<AllocationTableEntry>();var global=new List<string>();if(i.AllocationTableId!=null){table=await db.AllocationTables.SingleOrDefaultAsync(x=>x.Id==i.AllocationTableId&&x.CondominiumId==row.CondominiumId,ct)??throw new NotFoundException();if(table.Status!=AllocationTableStatus.Active||table.IsArchived||table.ValidFrom>i.ReferenceDate)throw new InvalidOperationException("Tabella non attiva o non valida alla data di riferimento.");entries=await db.AllocationTableEntries.Where(x=>x.AllocationTableId==table.Id&&x.ValidFrom<=i.ReferenceDate&&(x.ValidTo==null||x.ValidTo>=i.ReferenceDate)).ToListAsync(ct);}else global.Add("Tabella millesimale non selezionata: quote non determinate.");
  var result=new List<ParticipantUnit>();foreach(var unit in units){var hs=holdings.Where(x=>x.PropertyUnitId==unit.Id).ToArray();var anomalies=new List<string>();var owners=hs.Where(h=>h.Role is UnitPersonRole.Owner or UnitPersonRole.CoOwner).ToArray();if(hs.Length==0)anomalies.Add("Titolarità assente.");if(owners.Length>0&&owners.Sum(x=>x.Fraction??0)!=1)anomalies.Add("Quote di proprietà incomplete o incoerenti.");if(hs.GroupBy(h=>h.PersonId).Any(g=>g.Count()>1))anomalies.Add("Titolarità sovrapposte per uno stesso soggetto.");if(hs.Any(h=>h.Role is UnitPersonRole.Usufructuary or UnitPersonRole.Other))anomalies.Add("Titoli diversi dalla proprietà: diritto per argomento da verificare nella M07.2.");if(hs.Any(h=>!people.Any(p=>p.Id==h.PersonId&&p.IsActive)))anomalies.Add("Soggetto inattivo o mancante.");
   Guid? rep=null;var choice=i.Representatives.SingleOrDefault(x=>x.PropertyUnitId==unit.Id);if(choice!=null){if(!hs.Any(x=>x.PersonId==choice.PersonId))throw new ArgumentException("Rappresentante estraneo alla titolarità storica.");rep=choice.PersonId;}else if(hs.Length==1&&owners.Length==1&&owners[0].Fraction==1)rep=hs[0].PersonId;
   if(rep==null&&hs.Length>0)anomalies.Add("Rappresentanza unitaria da definire esplicitamente.");var es=entries.Where(x=>x.PropertyUnitId==unit.Id).ToArray();decimal? value=es.Length==1?es[0].Value:null;if(table!=null&&value==null)anomalies.Add("Quota millesimale assente o duplicata.");
   result.Add(new(unit.Id,unit.Code,value,hs.Select(h=>new ParticipantHolding(h.Id,h.PersonId,h.Role,h.Fraction,h.ValidFrom,h.ValidTo)).ToArray(),rep,anomalies));
  }
  if(table!=null&&(result.Any(u=>u.Millesimals==null)||result.Sum(u=>u.Millesimals??0)!=table.Denominator))global.Add("Totale quote non coincidente con il denominatore nominale; nessuna normalizzazione automatica.");
  if(result.Count==0)global.Add("Nessuna unità disponibile.");var ps=people.Select(p=>new ParticipantPerson(p.Id,p.DisplayName,p.Email,p.MailingAddress)).ToArray();var core=new{i.ReferenceDate,i.AllocationTableId,Denominator=table?.Denominator,People=ps,Units=result,Anomalies=global};return new(i.ReferenceDate,i.AllocationTableId,table?.Denominator,ps,result,Hash(core),global);
 }
 public Task<MeetingDetails> Consolidate(Guid condo,Guid id,ParticipantsInput i,CancellationToken ct)=>Mutate(condo,id,i.ExpectedVersion,"ParticipantsConsolidated",async row=>{
  if(row.Status==MeetingStatus.InProgress||await db.MeetingAttendances.AnyAsync(x=>x.MeetingId==id,ct))throw new InvalidOperationException("Snapshot non aggiornabile dopo l'inizio delle presenze.");
  if(await db.MeetingProxyUnits.AnyAsync(x=>x.MeetingId==id&&x.IsActive,ct))throw new InvalidOperationException("Revocare le deleghe attive prima di riconciliare uno snapshot.");var p=await BuildParticipants(row,i,ct);var version=1+(await db.MeetingSnapshots.Where(x=>x.MeetingId==id).MaxAsync(x=>(int?)x.Version,ct)??0);var snap=new MeetingSnapshot(Tenant,condo,id,version,i.ReferenceDate,i.AllocationTableId,Json(p),p.Fingerprint,i.Reason,Actor);db.Add(snap);await db.SaveChangesAsync(ct);row.Snapshot(snap.Id);if(row.Status==MeetingStatus.Convened)row.Reconcile();
 },ct);
 public Task<MeetingDetails> Notice(Guid condo,Guid id,NoticeInput i,CancellationToken ct)=>Mutate(condo,id,i.ExpectedVersion,"NoticePrepared",async row=>{
  var s=await Snapshot(row,ct);var p=s.People.SingleOrDefault(p=>p.Id==i.PersonId)??throw new NotFoundException();Guard.EnumValue(i.Channel);var contact=Guard.Text(i.Contact,1000);if(i.Channel is NoticeChannel.Email or NoticeChannel.PEC&&(!MailAddress.TryCreate(contact,out var address)||address.Address!=contact))throw new ArgumentException("Recapito email non valido.");
  if(await db.MeetingNotices.AnyAsync(x=>x.MeetingId==id&&x.SnapshotId==row.CurrentSnapshotId&&x.PersonId==i.PersonId&&x.Status!=Domain.NoticeStatus.Cancelled&&x.Status!=Domain.NoticeStatus.Failed,ct))throw new InvalidOperationException("Destinatario già preparato: registrare gli eventi o annullare il tentativo precedente.");
  db.Add(new MeetingNotice(Tenant,condo,id,row.CurrentSnapshotId!.Value,p.Id,p.Name,contact,i.Channel));
 },ct);
 public Task<MeetingDetails> NoticeStatus(Guid condo,Guid id,Guid notice,NoticeTransition i,CancellationToken ct)=>Mutate(condo,id,i.ExpectedVersion,"NoticeDeclared",async row=>{
  var n=await db.MeetingNotices.SingleOrDefaultAsync(x=>x.Id==notice&&x.MeetingId==id,ct)??throw new NotFoundException();if(n.SnapshotId!=row.CurrentSnapshotId)throw new InvalidOperationException("Convocazione di uno snapshot precedente: storico conservato.");n.Transition(i.Status,i.At);db.Add(new MeetingNoticeEvent(Tenant,condo,id,n.Id,i.Status,i.At,Actor,i.Reference,i.Notes));
 },ct);
 public Task<MeetingDetails> Proxy(Guid condo,Guid id,ProxyInput i,CancellationToken ct)=>Mutate(condo,id,i.ExpectedVersion,"ProxyCreated",async row=>{
  var s=await Snapshot(row,ct);if(i.PropertyUnitIds.Count==0||i.PropertyUnitIds.Distinct().Count()!=i.PropertyUnitIds.Count)throw new ArgumentException("Selezionare unità senza duplicati.");if(!s.People.Any(p=>p.Id==i.DelegatorId)||!await db.People.AnyAsync(p=>p.Id==i.DelegateId&&p.IsActive,ct))throw new NotFoundException();
  foreach(var uid in i.PropertyUnitIds){var u=s.Units.SingleOrDefault(u=>u.Id==uid)??throw new NotFoundException();if(u.RepresentativeId!=i.DelegatorId)throw new InvalidOperationException("Delegante non rappresentante consolidato dell'unità.");if(await db.MeetingProxyUnits.AnyAsync(x=>x.MeetingId==id&&x.PropertyUnitId==uid&&x.IsActive,ct)||await db.MeetingAttendanceUnits.AnyAsync(x=>x.MeetingId==id&&x.PropertyUnitId==uid&&x.IsActive,ct))throw new InvalidOperationException("Diritto già delegato o rappresentato in presenza.");}
  var proxy=new MeetingProxy(Tenant,condo,id,row.CurrentSnapshotId!.Value,i.DelegatorId,i.DelegateId,i.GrantedAt,i.Notes,i.DocumentReference,s.People.Single(p=>p.Id==i.DelegatorId).Name,(await db.People.SingleAsync(p=>p.Id==i.DelegateId,ct)).DisplayName);db.Add(proxy);foreach(var uid in i.PropertyUnitIds)db.Add(new MeetingProxyUnit(Tenant,condo,id,proxy.Id,uid));
 },ct);
 public Task<MeetingDetails> ProxyStatus(Guid condo,Guid id,Guid proxy,ProxyTransition i,CancellationToken ct)=>Mutate(condo,id,i.ExpectedVersion,"ProxyStatusChanged",async row=>{
  var p=await db.MeetingProxies.SingleOrDefaultAsync(x=>x.MeetingId==id&&x.Id==proxy,ct)??throw new NotFoundException();if(p.SnapshotId!=row.CurrentSnapshotId)throw new InvalidOperationException("Delega riferita a snapshot superato.");if(i.Status==Domain.ProxyStatus.Verified)current.RequireAdmin();if(await db.MeetingAttendances.AnyAsync(x=>x.ProxyId==proxy&&x.CheckOutAt==null,ct))throw new InvalidOperationException("Registrare prima l'uscita del delegato.");p.Transition(i.Status,Actor);if(i.Status is Domain.ProxyStatus.Rejected or Domain.ProxyStatus.Revoked)foreach(var unit in await db.MeetingProxyUnits.Where(x=>x.ProxyId==proxy&&x.IsActive).ToListAsync(ct))unit.Release();
 },ct);
 public Task<MeetingDetails> Attend(Guid condo,Guid id,AttendanceInput i,CancellationToken ct)=>Mutate(condo,id,i.ExpectedVersion,"AttendanceEntered",async row=>{
  if(row.Status!=MeetingStatus.InProgress)throw new InvalidOperationException("Avviare la sessione prima di registrare presenze.");var session=await db.MeetingSessions.SingleOrDefaultAsync(x=>x.MeetingId==id&&x.Id==i.SessionId,ct)??throw new NotFoundException();if(session.Status!=SessionStatus.InProgress)throw new InvalidOperationException("Sessione non in corso.");var s=await Snapshot(row,ct);if((i.PropertyUnitIds.Count==0&&i.Type==AttendanceType.ByProxy)||i.PropertyUnitIds.Count!=i.PropertyUnitIds.Distinct().Count())throw new ArgumentException("Selezionare diritti distinti.");Guid? by=null;
  if(i.Type==AttendanceType.ByProxy){var p=await db.MeetingProxies.SingleOrDefaultAsync(x=>x.Id==i.ProxyId&&x.MeetingId==id&&x.SnapshotId==row.CurrentSnapshotId&&x.Status==Domain.ProxyStatus.Verified,ct)??throw new InvalidOperationException("Delega verificata obbligatoria.");if(p.DelegatorId!=i.PersonId)throw new ArgumentException("Delegante incoerente.");by=p.DelegateId;var represented=await db.MeetingProxyUnits.Where(x=>x.ProxyId==p.Id&&x.IsActive).Select(x=>x.PropertyUnitId).ToArrayAsync(ct);if(i.PropertyUnitIds.Except(represented).Any())throw new ArgumentException("Unità non comprese nella delega.");}else{if(!s.People.Any(p=>p.Id==i.PersonId))throw new NotFoundException();if(i.Type==AttendanceType.Remote&&row.RemoteMeetingUrl==null)throw new InvalidOperationException("Modalità remota non configurata.");}
  if(i.PropertyUnitIds.Count==0&&await db.MeetingAttendances.AnyAsync(a=>a.MeetingId==id&&a.SessionId==i.SessionId&&a.PersonId==i.PersonId&&a.Type!=AttendanceType.ByProxy&&a.CheckOutAt==null,ct))throw new InvalidOperationException("Presenza fisica già registrata.");
  var att=new MeetingAttendance(Tenant,condo,id,i.SessionId,row.CurrentSnapshotId!.Value,i.PersonId,i.Type,i.ProxyId,by,i.CheckInAt,i.Notes);
  foreach(var uid in i.PropertyUnitIds){var u=s.Units.SingleOrDefault(u=>u.Id==uid)??throw new NotFoundException();if(u.RepresentativeId!=i.PersonId)throw new InvalidOperationException("Rappresentanza dell'unità non determinata o incoerente.");if(await db.MeetingAttendanceUnits.AnyAsync(x=>x.SessionId==i.SessionId&&x.PropertyUnitId==uid&&x.IsActive,ct))throw new InvalidOperationException("Diritto già rappresentato in questa convocazione.");if(i.Type!=AttendanceType.ByProxy&&await db.MeetingProxyUnits.AnyAsync(x=>x.MeetingId==id&&x.PropertyUnitId==uid&&x.IsActive,ct))throw new InvalidOperationException("Revocare la delega prima di registrare la presenza diretta.");db.Add(new MeetingAttendanceUnit(Tenant,condo,id,att.Id,i.SessionId,uid,u.Millesimals));}db.Add(att);
 },ct);
 public Task<MeetingDetails> Absence(Guid condo,Guid id,AbsenceInput i,CancellationToken ct)=>Mutate(condo,id,i.ExpectedVersion,"AbsenceDeclared",async row=>{var snap=await Snapshot(row,ct);if(!snap.People.Any(p=>p.Id==i.PersonId)||!await db.MeetingSessions.AnyAsync(x=>x.MeetingId==id&&x.Id==i.SessionId,ct))throw new NotFoundException();if(await db.MeetingAttendances.AnyAsync(x=>x.SessionId==i.SessionId&&x.PersonId==i.PersonId&&x.CheckOutAt==null,ct))throw new InvalidOperationException("Soggetto presente: registrare prima l'uscita.");db.Add(new MeetingAbsence(Tenant,condo,id,i.SessionId,i.PersonId,i.Reason));},ct);
 public Task<MeetingDetails> Leave(Guid condo,Guid id,Guid attendance,AttendanceExit i,CancellationToken ct)=>Mutate(condo,id,i.ExpectedVersion,"AttendanceExited",async row=>{var a=await db.MeetingAttendances.SingleOrDefaultAsync(x=>x.MeetingId==id&&x.Id==attendance,ct)??throw new NotFoundException();a.Leave(i.At);foreach(var u in await db.MeetingAttendanceUnits.Where(x=>x.AttendanceId==attendance&&x.IsActive).ToListAsync(ct))u.Release();},ct);
}
